"""
transition_matrix.py
--------------------
Generates an interactive transition matrix HTML visualization.

Usage:
    from transition_matrix import generate_transition_matrix
    generate_transition_matrix(df)
"""

import json
import os
import base64 as _b64
from collections import defaultdict

import pandas as pd


def _compute_transitions(df, user_col, session_col, time_col, event_col):
    """Compute transition counts and probabilities from event stream."""
    df = df[[user_col, session_col, time_col, event_col]].copy()
    df = df.sort_values([user_col, session_col, time_col])

    transition_counts = defaultdict(int)
    event_counts = defaultdict(int)
    current_key = None
    prev_event = None

    for row in df.itertuples(index=False):
        uid = getattr(row, user_col)
        sid = getattr(row, session_col)
        evt = getattr(row, event_col)
        key = (uid, sid)
        event_counts[evt] += 1
        if key == current_key and prev_event is not None:
            transition_counts[(prev_event, evt)] += 1
        current_key = key
        prev_event = evt

    source_totals = defaultdict(int)
    for (src, _), count in transition_counts.items():
        source_totals[src] += count

    edges_raw = []
    for (src, tgt), count in transition_counts.items():
        prob = round(count / source_totals[src], 4) if source_totals[src] > 0 else 0
        edges_raw.append((src, tgt, count, prob))

    node_degree = defaultdict(int)
    for src, tgt, count, _ in edges_raw:
        node_degree[src] += count
        node_degree[tgt] += count

    all_events = sorted(node_degree.keys(), key=lambda e: -node_degree[e])
    id_to_idx = {e: i for i, e in enumerate(all_events)}
    node_data = [[event_counts.get(e, 0), node_degree[e]] for e in all_events]

    edge_data = sorted(
        [[id_to_idx[s], id_to_idx[t], c, p] for s, t, c, p in edges_raw],
        key=lambda x: -x[2],
    )

    source_count_list = [source_totals.get(e, 0) for e in all_events]
    total_trans = sum(c for _, _, c, _ in edge_data)

    return all_events, node_data, edge_data, source_count_list, total_trans


# HTML template stored as base64 to avoid string escaping issues
_TMPL_BEFORE = _b64.b64decode("").decode("utf-8")
_TMPL_AFTER = _b64.b64decode("").decode("utf-8")


def generate_transition_matrix(
    df,
    user_col="UserID",
    session_col="SessionID",
    time_col="TimeStamp",
    event_col="Event",
    output_path="transition_matrix.html",
):
    """
    Generate an interactive transition matrix HTML visualization.

    Features:
      - Joint probability mode (entire matrix sums to 100%)
      - Conditional probability mode (each row sums to 100%)
      - Min probability slider with adaptive range per mode
      - Laplacian smoothing toggle with configurable alpha
      - Sort by frequency or alphabetical
      - Sequential or log color scale
      - Hover / click for detailed cell stats

    Parameters
    ----------
    df : pandas.DataFrame
    user_col, session_col, time_col, event_col : str
        Column names in df.
    output_path : str
        Output HTML file path.

    Returns
    -------
    str  — absolute path to the generated file.
    """
    for name, val in [("user_col", user_col), ("session_col", session_col),
                      ("time_col", time_col), ("event_col", event_col)]:
        if val not in df.columns:
            raise ValueError(
                f"Column '{val}' ({name}) not found. "
                f"Available: {list(df.columns)}"
            )

    print(f"Processing {len(df):,} rows...")

    node_ids, node_data, edge_data, source_counts, total_trans = _compute_transitions(
        df, user_col, session_col, time_col, event_col
    )

    print(f"  → {len(node_ids)} unique events")
    print(f"  → {len(edge_data):,} unique transitions")
    print(f"  → {total_trans:,} total transitions")

    data = {
        "ni": node_ids,
        "nd": node_data,
        "e": edge_data,
        "sc": source_counts,
        "tt": total_trans,
    }
    data_json = json.dumps(data, separators=(",", ":"))
    print(f"  → Data payload: {len(data_json) / 1024:.0f} KB")

    html = _TMPL_BEFORE + "const D=" + data_json + ";\n" + _TMPL_AFTER

    output_path = os.path.abspath(output_path)
    with open(output_path, "w", encoding="utf-8") as f:
        f.write(html)

    size_kb = os.path.getsize(output_path) / 1024
    print(f"\n✅ Generated: {output_path} ({size_kb:.0f} KB)")
    print(f"   Open in your browser to interact with the matrix.")

    return output_path
